from __future__ import annotations


def render_curation_page() -> str:
    """Standalone local UI: no CDN, no remote script and no secret-bearing URLs."""
    return '''<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RAMBLA Curation</title><style>
:root{--bg:#0b0d10;--panel:#15191f;--line:#29313b;--ink:#f4f7fa;--muted:#99a4b1;--lime:#d8ff5b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px system-ui,sans-serif}main{max-width:1450px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center}.muted{color:var(--muted)}button{border:1px solid var(--line);border-radius:8px;padding:8px 11px;background:#202832;color:var(--ink);font-weight:700;cursor:pointer}button.active{background:var(--lime);color:#10140b}#chunk-list{display:grid;gap:12px;margin-top:18px}.chunk{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:14px}.head{display:flex;justify-content:space-between;gap:8px}.shelves{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.shelf h3{font-size:12px;color:var(--muted);margin:0 0 6px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:8px}.asset{min-height:145px;overflow:hidden;text-align:left;padding:0;background:#10151a}.asset img,.asset video{display:block;width:100%;height:96px;object-fit:cover;background:#252b32}.asset .copy{padding:7px}.asset small{display:block;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.empty{color:var(--muted);padding:10px;border:1px dashed var(--line);border-radius:8px}dialog{max-width:min(95vw,1000px);background:#11161c;color:white;border:1px solid var(--line);padding:8px}dialog img{max-width:90vw;max-height:80vh}@media(max-width:760px){.shelves{grid-template-columns:1fr}}
</style><main><div class="top"><div><h1>RAMBLA Curation</h1><div class="muted">Selezione locale · Resolve calls = 0</div></div><div><button id="filter-selected">Solo selezionati</button> <b id="selection-summary">0 selezioni</b></div></div><div id="chunk-list"></div></main><dialog id="lightbox"><button onclick="lightbox.close()">CHIUDI</button><img id="lightbox-image"></dialog><script>
const $=id=>document.getElementById(id),sel=new Map();let only=false,data={chunks:[]};function esc(x){return String(x??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}function chosen(id){return sel.get(id)}function card(a){const is=chosen(a.asset_id);const media=a.preview_url?`<img src="${esc(a.preview_url)}" loading="lazy" alt="">`:'<div class="empty">Anteprima non disponibile</div>';return `<button class="asset ${is?'active':''}" data-id="${esc(a.asset_id)}" data-chunk="${esc(a.chunk_id)}" data-kind="${esc(a.kind)}" data-image="${esc(a.preview_url||'')}">${media}<div class="copy"><b>${esc(a.title||a.provider)}</b><small>${esc(a.rights_state)} · ${esc(a.orientation)}</small></div></button>`}function draw(){const chunks=only?data.chunks.filter(c=>c.assets.some(a=>chosen(a.asset_id))):data.chunks;$('chunk-list').innerHTML=chunks.map(c=>`<section class="chunk"><div class="head"><b>${esc(c.id)}</b><span class="muted">${esc(c.text)}</span></div><div class="shelves"><div class="shelf"><h3>VIDEO · fino a 3</h3><div class="cards">${c.assets.filter(a=>a.kind==='video').map(card).join('')||'<div class=empty>Nessun video pronto</div>'}</div></div><div class="shelf"><h3>IMMAGINI · fino a 4</h3><div class="cards">${c.assets.filter(a=>a.kind==='image').map(card).join('')||'<div class=empty>Nessuna immagine pronta</div>'}</div></div></div><button class="no-broll" data-chunk="${esc(c.id)}">NO BROLL</button></section>`).join('');document.querySelectorAll('.asset').forEach(x=>x.onclick=()=>toggle(x.dataset.chunk,x.dataset.id,x.dataset.kind));document.querySelectorAll('.no-broll').forEach(x=>x.onclick=()=>noBroll(x.dataset.chunk));$('selection-summary').textContent=`${sel.size} selezioni`;observePreviews()}function observePreviews(){new IntersectionObserver(es=>es.forEach(e=>{const v=e.target;if(e.isIntersecting&&v.dataset.previewVideo){v.src=v.dataset.previewVideo}})).observe(document.body)}async function save(){await fetch('/api/curation/run/default/selection',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({selections:Object.fromEntries(sel)})})}async function toggle(chunk,id,kind){if(sel.get(chunk)==='NO_BROLL')sel.delete(chunk);if(sel.get(chunk)===id)sel.delete(chunk);else sel.set(chunk,id);await save();draw()}async function noBroll(chunk){sel.set(chunk,'NO_BROLL');await save();draw()}$('filter-selected').onclick=()=>{only=!only;$('filter-selected').classList.toggle('active',only);draw()};fetch('/api/curation/run/default').then(r=>r.json()).then(x=>{data=x;Object.entries(x.selections||{}).forEach(([k,v])=>sel.set(k,v));draw()});
// IntersectionObserver is deliberately used so local MP4 previews may be lazy-attached on future video cards.
</script></html>'''
